# Count table for Jie, final definitions, from frozen R1. (a) known complexes, as v2 minus pairs moved to (b): WIZ-ZNF644, RBBP4-ZNF512B, ADNP-HP1. (b) recently revealed. (c) novel, AF3-supported: AF3 strong and not in STRING/CORUM/CAP-SELEX.
import numpy as np, pandas as pd
X = "/work/users/d/y/dyy12/XuLab"; O = f"{X}/complex_screen/complex_counts"; P = pd.read_csv(f"{X}/regulatome/r1_tftf/v2_final/r1_pairs_frozen.tsv", sep="\t", keep_default_na=False, na_values=[""])
key = lambda a, b: "__".join(sorted((a, b))); P["k"] = [key(a, b) for a, b in zip(P.a, P.b)]; P = P.set_index("k")
A = pd.read_csv(f"{O}/a_known_complexes_v2.tsv", sep="\t"); MOVED = {"G9a/GLP scaffold (WIZ-ZNF644)": "moved to (b)", "NuRD + ZNF512B": "moved to (b)", "ChAHP (ADNP-HP1)": "moved to (b)"}; A3 = A[~A.complex.isin(MOVED)].copy()
def col(c, s, f): return [",".join(str(f(P.loc[p, c])) for p in x.split(",")) if x != "." else "." for x in s]
A3["class_final"] = col("class", A3.pairs_used, str); A3["af3_tier"] = col("af3_tier", A3.pairs_used, str); A3["boltz_full_tier"] = col("boltz_full_tier", A3.pairs_used, str); A3.to_csv(f"{O}/a_known_complexes_v3.tsv", sep="\t", index=False)
RB = [("FOXK1", "MLX", "CAP-SELEX 2025 (Xie et al.)"), ("MLX", "MSX2", "CAP-SELEX 2025 (Xie et al.)"), ("HOXD10", "SREBF2", "CAP-SELEX 2025 (Xie et al.)"), ("WIZ", "ZNF644", "G9a/GLP literature; moved from (a)"),
      ("RBBP4", "ZNF512B", "Nucleic Acids Res 2024, doi 10.1093/nar/gkae926; moved from (a)"), ("ADNP", "HP1", "Ostapcuk et al., Nature 2018, doi 10.1038/s41586-018-0153-8; moved from (a)")]
b = [dict(pair=key(a, c), source=s, class_final=P.loc[key(a, c), "class"], w=P.loc[key(a, c), "w"], cobinding_edge=bool(P.loc[key(a, c), "view1"]), boltz_trimmed=P.loc[key(a, c), "boltz_trimmed_tier"], boltz_full=P.loc[key(a, c), "boltz_full_tier"], af3_tier=P.loc[key(a, c), "af3_tier"], flags=P.loc[key(a, c), "flags"]) for a, c, s in RB]; B = pd.DataFrame(b); B.to_csv(f"{O}/b_recently_revealed_v3.tsv", sep="\t", index=False)
known = P.string_physical.notna() | P.capselex.astype(str).str.startswith("called"); N = P[P.af3_tier.eq("strong") & ~known]
Cc = N[["a", "b", "class", "w", "view1", "boltz_trimmed_tier", "boltz_full_tier", "af3_tier", "af3_iptm", "af3_ipsae", "af3_seeds_strong", "hub_partner", "flags"]].copy(); Cc["status"] = np.where(Cc["flags"].str.contains("not_expressed"), "listed, excluded: not expressed", "novel, AF3-supported"); Cc.to_csv(f"{O}/c_novel_af3_supported_v3.tsv", sep="\t", index=False)
Pc = pd.read_csv(f"{O}/c_candidates_pending_AF3_v2.tsv", sep="\t", keep_default_na=False); Pc["af3_tier"] = [P.loc[k, "af3_tier"] for k in Pc.pair]; Pc["class_final"] = [P.loc[k, "class"] for k in Pc.pair]; Pc["category"] = "co-binding candidate, AF3 complete"; Pc.drop(columns=["af3_iptm", "af3_ipsae", "class_with_rulings"], errors="ignore").to_csv(f"{O}/c_cobinding_candidates_v3.tsv", sep="\t", index=False)
sc = A3[A3.recovered_deck_rule.astype(str) != "not scored"]
S = pd.DataFrame([dict(category="(a) known complexes scored", n=len(sc), detail=f"enrichment matrix >= 0.90: {int((sc.recovered_deck_rule.astype(str) == 'True').sum())}; >= 1 co-binding edge: {int((sc.recovered_ge1_edge.astype(str) == 'True').sum())}; WIZ-ZNF644, ZNF512B-RBBP4, ADNP-HP1 moved to (b)"),
                  dict(category="(b) recently revealed", n=len(B), detail=f"{int(B.cobinding_edge.sum())} with a co-binding edge"), dict(category="(c) novel, AF3-supported", n=int((Cc.status == "novel, AF3-supported").sum()), detail=", ".join(f"{a}-{c}" for a, c in zip(Cc.a[Cc.status == "novel, AF3-supported"], Cc.b[Cc.status == "novel, AF3-supported"]))),
                  dict(category="(c) listed, excluded", n=int((Cc.status != "novel, AF3-supported").sum()), detail=", ".join(f"{a}-{c}" for a, c in zip(Cc.a[Cc.status != "novel, AF3-supported"], Cc.b[Cc.status != "novel, AF3-supported"])))]); S.to_csv(f"{O}/summary_v3.tsv", sep="\t", index=False)
pd.set_option("display.width", 220); pd.set_option("display.max_columns", 20); pd.set_option("display.max_colwidth", 80); print(S.to_string(index=False)); print(A3[["complex", "pairs_used", "mean_pair_pct_enrichment", "recovered_deck_rule", "recovered_ge1_edge", "class_final", "af3_tier"]].to_string(index=False)); print(B.drop(columns="source").to_string(index=False)); print(Cc.round(2).to_string(index=False))
